import { task, launchBrowser, writeResult, clip, SCREENSHOT_PATH } from "/opt/teger/scout-kit.mjs";

const browser = await launchBrowser();
const page = await browser.newPage();
const nav = await page.goto(task.url);

// Always capture the screenshot early so a later extraction failure cannot
// lose the preview (fixes the prior crash that happened before screenshot).
let screenshot = { path: SCREENSHOT_PATH, bytes: 0 };
let screenshotError = null;
try {
  const shot = await page.screenshot();
  screenshot = { path: shot.path, bytes: shot.bytes };
} catch (e) {
  screenshotError = String(e?.message ?? e);
}

// Give slow pages a bounded chance to render.
try {
  await page.waitFor(() => document.readyState === "complete" && document.body, { timeoutMs: 4000, intervalMs: 100 });
} catch {
  // fall through; continue with whatever rendered
}

const extractionErrors = [];
let title = null;
let claimedIdentity = { siteName: null, brandMentions: [], evidence: [] };
let forms = [];
let loginFormDetected = false;
let textSignals = { urgencyPhrases: [], credentialRequests: [], instructionsToAI: [] };
let visibleTextSample = "";
let externalScriptOrigins = [];

try {
  const doc = await page.evaluate(() => {
    const walk = (el) => {
      const out = [];
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_ELEMENT, {
        acceptNode(n) { return (n.tagName === "SCRIPT" || n.hidden) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; }
      });
      let n;
      while ((n = walker.nextNode())) out.push(n);
      return out;
    };

    const meta = (name) => {
      const m = document.querySelector(`meta[property="${name}"],meta[name="${name}"]`);
      return m ? m.content : null;
    };

    const siteName = meta("og:site_name") || meta("application-name");
    const brandMentions = [];
    const evidence = [];
    if (document.title) { brandMentions.push(document.title); evidence.push(`<title>: ${document.title}`); }
    const logo = document.querySelector("img[alt][src*='logo' i], img[alt], [data-logo] img, .logo img");
    if (logo && logo.alt) { brandMentions.push(logo.alt); evidence.push(`logo alt: ${logo.alt}`); }
    if (siteName) { brandMentions.push(siteName); evidence.push(`meta: ${siteName}`); }

    const formsArr = [];
    const formEls = Array.from(document.forms);
    // also catch forms hidden in open shadow roots
    const roots = Array.from(document.querySelectorAll("*")).flatMap((e) => {
      const sr = e.shadowRoot;
      return sr ? [sr] : [];
    });
    for (const r of roots) {
      try { Array.from(r.querySelectorAll("form")).forEach((f) => formEls.push(f)); } catch {}
    }
    const seenPw = [];
    for (const f of formEls) {
      const inputs = [];
      try { Array.from(f.elements).forEach((i) => { if (i.tagName === "INPUT" || i.tagName === "TEXTAREA" || i.tagName === "SELECT") inputs.push(i); }); } catch {}
      const pw = inputs.some((i) => i.type === "password");
      if (pw) seenPw.push(f);
      let action = null;
      try { action = new URL(f.getAttribute("action") || location.href, location.href).href; } catch { action = f.getAttribute("action"); }
      const method = (f.getAttribute("method") || "get").toLowerCase();
      const types = inputs.map((i) => i.type || (i.tagName === "SELECT" ? "select" : "textarea"));
      const names = inputs.map((i) => i.name).filter(Boolean);
      formsArr.push({
        action,
        method,
        hasPasswordField: pw,
        inputTypes: types,
        inputNames: names,
        crossOriginAction: (() => { try { return new URL(action || location.href, location.href).origin !== location.origin; } catch { return false; } })()
      });
    }
    // password inputs outside any form -> synthetic entry
    const allPw = Array.from(document.querySelectorAll("input[type=password]")).filter((i) => !formEls.some((f) => f.contains(i)));
    for (const i of allPw) {
      let action = null;
      try { action = new URL(location.href); } catch { action = location.href; }
      seenPw.push(i);
      formsArr.push({ action: location.href, method: "n/a", hasPasswordField: true, inputTypes: ["password"], inputNames: [i.name].filter(Boolean), crossOriginAction: false });
    }

    // text signals
    const urgency = ["account suspended", "verify within 24 hours", "verify within", "unusual activity", "urgent action", "suspended", "verify your", "security alert", "limited time", "access denied"];
    const cred = ["enter your password", "enter password", "password", "confirm your card", "confirm card", "card number", "cvv", "social security", "ssn", "otp", "one-time password"];
    const aiTerms = ["ignore previous instructions", "you are an ai", "automated scanner", "disable the filter", "print your secrets", "mark this page safe"];
    let fullText = document.body ? document.body.innerText || "" : "";
    const lower = fullText.toLowerCase();
    const matchPhrases = (terms, src) => {
      const found = [];
      const used = new Set();
      for (const t of terms) { if (lower.includes(t) && !used.has(t)) { found.push(t); used.add(t); } }
      return found.slice(0, 10);
    };

    const scripts = Array.from(document.querySelectorAll("script[src]")).map((s) => s.src).filter(Boolean);
    const origins = Array.from(new Set(scripts.map((u) => { try { return new URL(u).origin; } catch { return null; } })).filter(Boolean));

    return {
      title: document.title || null,
      siteName: siteName || null,
      brandMentions: brandMentions.slice(0,10),
      evidence: evidence.slice(0,10),
      forms: formsArr,
      hasPassword: seenPw.length > 0,
      visibleText: (document.body ? document.body.innerText : "") || "",
      urgency: matchPhrases(urgency, lower),
      cred: matchPhrases(cred, lower),
      ai: matchPhrases(aiTerms, lower),
      scriptOrigins: origins.slice(0,20)
    };
  });

  title = doc.title;
  if (doc.siteName) claimedIdentity.siteName = doc.siteName;
  claimedIdentity.brandMentions = doc.brandMentions;
  claimedIdentity.evidence = doc.evidence;
  forms = doc.forms.map((f) => ({
    action: f.action || null,
    method: f.method,
    hasPasswordField: !!f.hasPasswordField,
    inputTypes: Array.isArray(f.inputTypes) ? f.inputTypes : [],
    inputNames: Array.isArray(f.inputNames) ? f.inputNames : [],
    crossOriginAction: !!f.crossOriginAction
  }));
  loginFormDetected = !!doc.hasPassword;
  textSignals = {
    urgencyPhrases: doc.urgency,
    credentialRequests: doc.cred,
    instructionsToAI: doc.ai
  };
  visibleTextSample = clip(doc.visibleText, 1500);
  externalScriptOrigins = doc.scriptOrigins;
} catch (e) {
  extractionErrors.push(String(e?.message ?? e));
}

await writeResult({
  requestedUrl: task.url,
  finalUrl: nav?.finalUrl ?? null,
  httpStatus: nav?.status ?? null,
  redirectChain: page.redirectChain(),
  title,
  claimedIdentity,
  forms,
  loginFormDetected,
  textSignals,
  visibleTextSample,
  externalScriptOrigins,
  blockedRequests: page.blockedRequests(),
  contactedHosts: page.contactedHosts(),
  screenshot,
